import java.io.*;import java.security.*;import java.util.*;import org.concentus.*;
public class CodecPortTest{public static void main(String[] args)throws Exception{File[] files=new File(args[0]).listFiles();Arrays.sort(files);MessageDigest h=MessageDigest.getInstance("SHA-256");int clips=0,packets=0;long start=System.nanoTime();for(File f:files)if(f.getName().endsWith(".packets")){DataInputStream in=new DataInputStream(new FileInputStream(f));if(in.readInt()!=0x4f504b31)throw new Exception();int count=in.readInt();SilkNbOnlyProbe decoder=new SilkNbOnlyProbe();for(int i=0;i<count;i++){byte[] data=new byte[in.readUnsignedShort()];in.readFully(data);short[] pcm=new short[240];if(decoder.decode(data,pcm)!=240)throw new Exception();for(short s:pcm){h.update((byte)s);h.update((byte)(s>>8));}packets++;}in.close();clips++;}String hash="";for(byte b:h.digest())hash+=Integer.toHexString((b&255)|256).substring(1);if(!hash.equals("f3d30baf91a5fa35752d03fa377a6ad991ed1be19b53e79b541344079d366241"))throw new Exception(hash);System.out.println("CLDC codec exact: clips="+clips+" packets="+packets+" ms="+(System.nanoTime()-start)/1000000);}}
